use std :: collections :: HashMap ; use std :: fs ; use std :: io ; use std :: path :: Path ; impl ProjectSelfCoverage { fn new () -> Self { ProjectSelfCoverage { total_files : 0 , test_files : 0 , covered_files : 0 , coverage_percentage : 0.0 , performance_score : 0.0 , test_success_rate : 0.0 , complexity_score : 0.0 , mathematical_groups : Vec :: new () , group_family : "Unclassified" . to_string () , group_order : "1" . to_string () , group_rank : 0 , file_categories : HashMap :: new () , test_categories : HashMap :: new () , } } fn analyze_project_structure (& mut self) -> io :: Result < () > { let project_root = "." ; let test_dirs = vec ! ["tests" , "src/tests"] ; let source_dirs = vec ! ["src" , "src/bin"] ; for dir in source_dirs { if Path :: new (dir) . exists () { self . analyze_directory (dir , false) ? ; } } for dir in test_dirs { if Path :: new (dir) . exists () { self . analyze_directory (dir , true) ? ; } } if self . total_files > 0 { self . coverage_percentage = (self . covered_files as f64 / self . total_files as f64) * 100.0 ; } self . calculate_complexity () ; self . classify_group_family () ; Ok (()) } fn analyze_directory (& mut self , path : & str , is_test : bool) -> io :: Result < () > { if ! Path :: new (path) . exists () { return Ok (()) ; } for entry in fs :: read_dir (path) ? { let entry = entry ? ; let path = entry . path () ; if path . is_dir () { self . analyze_directory (path . to_str () . unwrap_or ("") , is_test) ? ; } else if let Some (ext) = path . extension () { let ext_str = ext . to_string_lossy () . to_lowercase () ; if ext_str == "rs" { if is_test { self . test_files += 1 ; * self . test_categories . entry (ext_str . clone ()) . or_insert (0) += 1 ; } else { self . total_files += 1 ; * self . file_categories . entry (ext_str . clone ()) . or_insert (0) += 1 ; } } } } Ok (()) } fn calculate_complexity (& mut self) { let file_diversity = self . file_categories . len () as f64 ; let test_diversity = self . test_categories . len () as f64 ; let size_factor = (self . total_files as f64) . log10 () ; let test_ratio = if self . total_files > 0 { self . test_files as f64 / self . total_files as f64 } else { 0.0 } ; self . complexity_score = (file_diversity * 0.3) + (test_diversity * 0.2) + (size_factor * 0.3) + (test_ratio * 100.0 * 0.2) ; self . performance_score = self . coverage_percentage . min (100.0) * 0.6 + (test_ratio * 100.0) . min (100.0) * 0.4 ; self . test_success_rate = (self . coverage_percentage * 0.8 + 20.0) . min (100.0) ; } fn classify_group_family (& mut self) { let complexity = self . complexity_score ; let coverage = self . coverage_percentage ; let performance = self . performance_score ; if complexity < 1.5 && coverage < 30.0 { self . group_family = "Cyclic" . to_string () ; self . group_order = "2" . to_string () ; self . group_rank = 1 ; self . mathematical_groups = vec ! ["C2" . to_string ()] ; } else if complexity < 2.5 && coverage < 60.0 { self . group_family = "Alternating" . to_string () ; let n = (complexity * 3.0) . ceil () as usize ; self . group_order = format ! ("{}" , n * (n - 1) / 2) ; self . group_rank = n - 2 ; self . mathematical_groups = vec ! [format ! ("A{}" , n)] ; } else if complexity < 3.5 && coverage < 80.0 { self . group_family = "Lie Type" . to_string () ; let rank = ((complexity - 2.0) * 2.0) . ceil () as usize ; self . group_order = format ! ("{}" , 2_i32 . pow ((rank * (rank - 1) / 2) as u32) as usize * 1000) ; self . group_rank = rank ; self . mathematical_groups = vec ! [format ! ("PSL({}, 2)" , rank)] ; } else { self . group_family = "Sporadic" . to_string () ; self . group_order = "7920" . to_string () ; self . group_rank = 0 ; self . mathematical_groups = vec ! ["Monster Group" . to_string ()] ; } } fn get_coverage_color (& self) -> String { match self . coverage_percentage { score if score >= 80.0 => "[🟢]" . to_string () , score if score >= 60.0 => "[🟠]" . to_string () , score if score >= 40.0 => "[🟡]" . to_string () , score if score >= 20.0 => "[🔴]" . to_string () , _ => "[🔴]" . to_string () , } } fn get_performance_color (& self) -> String { match self . performance_score { score if score >= 80.0 => "[🔵]" . to_string () , score if score >= 60.0 => "[🟣]" . to_string () , score if score >= 40.0 => "[🟡]" . to_string () , score if score >= 20.0 => "[🔴]" . to_string () , _ => "[🔴]" . to_string () , } } fn get_test_success_color (& self) -> String { match self . test_success_rate { score if score >= 80.0 => "[🟢]" . to_string () , score if score >= 60.0 => "[🟠]" . to_string () , score if score >= 40.0 => "[🟡]" . to_string () , score if score >= 20.0 => "[🔴]" . to_string () , _ => "[🔴]" . to_string () , } } fn get_group_theory_description (& self) -> String { match self . group_family . as_str () { "Cyclic" => format ! ("Cyclic group of order {} - Prime order simple group" , self . group_order) , "Alternating" => format ! ("Alternating group A_{} - Non-abelian simple group" , self . group_rank + 2) , "Lie Type" => format ! ("Lie type group PSL({}, 2) - Classical simple group" , self . group_rank) , "Sporadic" => format ! ("Sporadic group {} - Exceptional simple group" , self . mathematical_groups . first () . unwrap_or (& "Unknown" . to_string ())) , _ => "Unclassified group" . to_string () , } } fn render_tile (& self , selected : bool) -> io :: Result < () > { let width = 80 ; let selected_marker = if selected { "► " } else { "  " } ; print ! ("{}" , selected_marker) ; for _ in 0 .. width { print ! ("─") ; } println ! () ; print ! ("{}│" , selected_marker) ; print ! ("🎯 Project Self-Coverage Analysis ") ; print ! ("{}📊 {:.1}% " , self . get_coverage_color () , self . coverage_percentage) ; print ! ("{}⚡ {:.1}% " , self . get_performance_color () , self . performance_score) ; print ! ("{}🧪 {:.1}% " , self . get_test_success_color () , self . test_success_rate) ; for _ in 0 .. (width - 2 - 50) { print ! (" ") ; } println ! ("│") ; print ! ("{}│" , selected_marker) ; print ! ("🔢 Group: {} | 📊 Complexity: {:.2} | 🧪 Mathematical: {}" , self . group_family , self . complexity_score , self . get_group_theory_description ()) ; for _ in 0 .. (width - 2 - 80) { print ! (" ") ; } println ! ("│") ; print ! ("{}│" , selected_marker) ; print ! ("📁 Files: {} | 🧪 Tests: {} | ✅ Covered: {} | 📊 Coverage: {:.1}%" , self . total_files , self . test_files , self . covered_files , self . coverage_percentage) ; for _ in 0 .. (width - 2 - 70) { print ! (" ") ; } println ! ("│") ; print ! ("{}│" , selected_marker) ; print ! ("📁 Source Files: {} | 🧪 Test Files: {} | 🔬 Categories: {}" , self . total_files - self . test_files , self . test_files , self . file_categories . len ()) ; for _ in 0 .. (width - 2 - 65) { print ! (" ") ; } println ! ("│") ; print ! ("{}│" , selected_marker) ; print ! ("🔬 Mathematical Groups: {}" , self . mathematical_groups . join (", ")) ; for _ in 0 .. (width - 2 - 35) { print ! (" ") ; } println ! ("│") ; print ! ("{}" , selected_marker) ; for _ in 0 .. width { print ! ("─") ; } println ! () ; Ok (()) } fn render_detailed (& self) -> io :: Result < () > { println ! ("🎯 Project Self-Coverage Analysis") ; println ! ("=================================") ; println ! ("📊 Coverage: {:.1}% {}" , self . coverage_percentage , self . get_coverage_color ()) ; println ! ("⚡ Performance: {:.1}% {}" , self . performance_score , self . get_performance_color ()) ; println ! ("🧪 Test Success: {:.1}% {}" , self . test_success_rate , self . get_test_success_color ()) ; println ! ("🔢 Complexity Score: {:.2}" , self . complexity_score) ; println ! ("📁 Total Files: {}" , self . total_files) ; println ! ("🧪 Test Files: {}" , self . test_files) ; println ! ("✅ Covered Files: {}" , self . covered_files) ; println ! ("🔬 Mathematical Family: {}" , self . group_family) ; println ! ("📊 Group Order: {}" , self . group_order) ; println ! ("🧪 Group Rank: {}" , self . group_rank) ; println ! ("🔬 Mathematical Groups: {}" , self . mathematical_groups . join (", ")) ; println ! ("📋 Group Theory Description: {}" , self . get_group_theory_description ()) ; println ! () ; println ! ("📁 File Categories:") ; for (ext , count) in & self . file_categories { println ! ("   {}: {} files" , ext , count) ; } println ! () ; println ! ("🧪 Test Categories:") ; for (ext , count) in & self . test_categories { println ! ("   {}: {} test files" , ext , count) ; } println ! () ; Ok (()) } }